import sys
from rich.traceback import Traceback

def recursive_func(n):
    if n > 0:
        recursive_func(n - 1)
    else:
        raise RuntimeError("Deep recursion!")

try:
    # Set recursion limit high enough to trigger the issue but not crash the process immediately
    sys.setrecursionlimit(2000)
    recursive_func(1000)
except RuntimeError as e:
    try:
        # This is where the RecursionError might happen if Traceback.extract is recursive
        # and the traceback is deep.
        # However, the diagnosis mentions ExceptionGroup/BaseExceptionGroup recursion.
        # Let's try to create a deeply nested ExceptionGroup.

        print("Testing deep ExceptionGroup recursion...")
        eg = RuntimeError("Base")
        for i in range(1000):
            eg = ExceptionGroup("Group", [eg])

        Traceback.extract(type(eg), eg, eg.__traceback__)
        print("Successfully extracted deep ExceptionGroup")
    except RecursionError:
        print("Caught RecursionError!")
        sys.exit(1)
    except Exception as ex:
        print(f"Caught unexpected exception: {ex}")
        sys.exit(1)

print("Finished without RecursionError")
